SELECT 
        mc.id_turma AS turma, 
        mc.id_matricula_componente,
        CASE 
            WHEN crc.id_tipo_avaliacao_componente_relatorio = 1 AND :bimestre_filtro < 4 
                THEN TRUE
            WHEN crc.id_tipo_avaliacao_componente_relatorio = 1 AND :bimestre_filtro = 4 
                THEN (rac.avaliacao_descritiva <> '' AND rac.avaliacao_descritiva IS NOT NULL)
            WHEN crc.id_tipo_avaliacao_componente_relatorio = 2 
                THEN (rahr.id_opcao_grupo_avaliacao_relatorio IS NOT NULL)
            ELSE FALSE 
        END AS resposta
    FROM ensino.matricula_componente mc
    -- O segredo está nestes LEFT JOINs abaixo:
    LEFT JOIN ensino_infantil.relatorio_avaliativo_componente rac  ON rac.id_matricula_componente = mc.id_matricula_componente
    LEFT JOIN ensino_infantil.configuracao_relatorio_componente crc ON crc.id_configuracao_relatorio_componente = rac.id_configuracao_relatorio_componente
    LEFT JOIN ensino_infantil.relatorio_avaliativo ra ON ra.id_relatorio_avaliativo = rac.id_relatorio_avaliativo
    LEFT JOIN ensino_infantil.relatorio_avaliativo_habilidade_resposta rahr ON rahr.id_relatorio_avaliativo_habilidade = mc.id_matricula_componente AND rahr.periodo = 1
    WHERE mc.ano = 2026 AND ra.ativo;

